function buildSparseTable(arr) {
  const n = arr.length;
  const LOG = Math.floor(Math.log2(n)) + 1;

  // st[i][j] = min of arr[i .. i + 2^j - 1]
  const st = Array.from({ length: n }, () => new Array(LOG).fill(0));

  // base case: ranges of length 1
  for (let i = 0; i < n; i++) st[i][0] = arr[i];

  // fill by increasing power of 2
  for (let j = 1; j < LOG; j++) {
    for (let i = 0; i + (1 << j) <= n; i++) {
      st[i][j] = Math.min(st[i][j - 1], st[i + (1 << (j - 1))][j - 1]);
    }
  }

  // precompute log table to avoid Math.log2 in every query
  const logTable = new Array(n + 1).fill(0);
  for (let i = 2; i <= n; i++) logTable[i] = logTable[i >> 1] + 1;

  // O(1) range minimum query
  function query(l, r) {
    const k = logTable[r - l + 1];
    return Math.min(st[l][k], st[r - (1 << k) + 1][k]);
  }

  return query;
}

// Usage
const rmq = buildSparseTable([2, 4, 3, 1, 6, 7, 8, 9, 1, 7]);
console.log(rmq(0, 4)); // min of arr[0..4] = 1
console.log(rmq(2, 7)); // min of arr[2..7] = 1
